SELECT * FROM monitor_sys_gen_script 
WHERE monitor_sys_gen_script_type = #{scriptType} 
AND monitor_sys_gen_script_status = 1


SELECT * FROM monitor_sys_gen_script 
WHERE monitor_sys_gen_script_category = #{category} 
AND monitor_sys_gen_script_status = 1

mapper.update:

UPDATE monitor_sys_gen_script SET 
    monitor_sys_gen_script_execute_count = monitor_sys_gen_script_execute_count + 1, 
    monitor_sys_gen_script_last_execute_time = #{executeTime} 
WHERE monitor_sys_gen_script_id = #{scriptId}
